    public function resolve(string $office,string $acceptanceId):array
    {
        [$role,$seat,$subordinate]=match($office){'hagiography'=>['sanctographer','hagiography.sanctographer','Chronicler'],'studium'=>['chancellor','studium.chancellor','Notary'],default=>throw new \InvalidArgumentException('A79_AUTHORSHIP_OFFICE_INVALID')};if(!preg_match('/^'.$office.'-acceptance-[a-f0-9]{20}$/',$acceptanceId))throw new \InvalidArgumentException('A83_ACCEPTANCE_INVALID');$acceptance=$this->read($this->officeRoot.'/'.$office.'/acceptances/'.$acceptanceId.'.json','A84_ACCEPTANCE_ABSENT');
        if(!$this->digestMatches($acceptance)||'imperium.authorship-commission-acceptance/v1'!==($acceptance['schema']??null)||'ACCEPTED_FOR_RESIDENT_AUTHORSHIP'!==($acceptance['disposition']??null)||true!==($acceptance['recipient_acceptance']??null)||true!==($acceptance['authorship_authority_exercisable']??null)||true!==($acceptance['subordinate_staff_resolution_authority']??null)||true!==($acceptance['subordinate_staff_resolution_pending']??null)||$subordinate!==($acceptance['subordinate_staff_class']??null)||true===($acceptance['execution_authority']??null))throw new \RuntimeException('A85_ACCEPTANCE_INVALID');
        $commissionId=$acceptance['commission_id']??null;$commission=is_string($commissionId)?$this->read($this->officeRoot.'/'.$office.'/inbox/'.$commissionId.'.json','A86_COMMISSION_ABSENT'):[];$bindingId=$acceptance['binding_id']??null;$binding=is_string($bindingId)?$this->read($this->officeRoot.'/'.$office.'/occupancy/'.$bindingId.'.json','A87_OCCUPANCY_ABSENT'):[];
        if(!$this->digestMatches($commission)||($acceptance['commission_digest']??null)!==($commission['record_digest']??null)||$seat!==($commission['target_seat']??null)||true!==($commission['authorship_authority']??null)||true===($commission['execution_authority']??null))throw new \RuntimeException('A88_COMMISSION_CHANGED');if(!$this->digestMatches($binding)||($acceptance['binding_digest']??null)!==($binding['record_digest']??null)||'ACTIVE'!==($binding['status']??null)||$seat!==($binding['seat']??null)||true!==($binding['subordinate_staff_resolution_authority']??null))throw new \RuntimeException('A89_OCCUPANCY_CHANGED');
